const entrada = $input.first()?.json ?? {};

const errores = [];

const idActivo = Number(entrada.params?.id_activo);
const body = entrada.body ?? {};

if (
  !Number.isSafeInteger(idActivo) ||
  idActivo <= 0
) {
  errores.push(
    "id_activo debe ser un entero positivo."
  );
}

const revisadoPor =
  typeof body.revisado_por === "string"
    ? body.revisado_por.trim()
    : "";

if (!revisadoPor) {
  errores.push(
    "revisado_por es obligatorio."
  );
}

const comentario = body.comentario_curaduria;

if (
  comentario !== undefined &&
  comentario !== null &&
  typeof comentario !== "string"
) {
  errores.push(
    "comentario_curaduria debe ser una cadena de texto."
  );
}

return [{
  json: {
    valido: errores.length === 0,
    errores,
    id_activo: idActivo,
    comentario_curaduria:
      typeof comentario === "string"
        ? comentario.trim()
        : null,
    revisado_por: revisadoPor
  }
}];

